import sys

data = sys.stdin.read().split()
n = int(data[0])
a = list(map(int, data[1:1 + n]))
def isp(v):
    if v < 2:
        return False
    d = 2
    while d * d <= v:
        if v % d == 0:
            return False
        d += 1
    return True
c = 0
for i in range(n - 1):
    if isp(a[i] + a[i + 1]):
        c += 1
print(c)

